# players.py: kid-friendly "Who's playing today?" page (StartScreen) + small Playful/flows.spec updates.
import base64, hashlib, sys
EXPECT = {'app/src/screens/StartScreen.tsx': 'ee277545265268a4818b1567590c3abd', 'app/src/components/Playful.tsx': '8acf6804e2687aa467b540242bfda3c6'}
for p, m in EXPECT.items():
    got = hashlib.md5(open(p, 'rb').read()).hexdigest()
    if got != m: sys.exit(f'{p} changed since staging ({got}); not applying')
f = 'app/e2e/flows.spec.ts'
s = open(f, encoding='utf-8').read()
OLD = """  await page.getByRole('button', { name: /Choose an adventure/ }).click();

  const header = page.getByTestId('app-header');
  await expect(header).toBeVisible();
"""
NEW = """  await page.getByRole('button', { name: /Choose an adventure/ }).click();

  const header = page.getByTestId('app-header');
  await expect(header).toBeVisible();
  // Reaching the button scrolls the player page, which shrinks the bar; let it
  // grow back on the new screen before measuring it.
  await expect(page.getByRole('button', { name: 'Open the Play Zone games' })).toBeVisible();
  await page.waitForTimeout(400);
"""
if s.count(OLD) != 1: sys.exit('flows.spec.ts: anchor not found exactly once; not applying')
PAYLOAD = {'app/src/components/Playful.tsx': '', 'app/src/screens/StartScreen.tsx': ''}
WANT = {'app/src/components/Playful.tsx': '627f9f5d548d0b3153ffa47c7ac94019', 'app/src/screens/StartScreen.tsx': '1f9ee808150ede4a439931a2d2f01857'}
for p, b in PAYLOAD.items():
    open(p, 'wb').write(base64.b64decode(b))
    assert hashlib.md5(open(p, 'rb').read()).hexdigest() == WANT[p], p
    print('wrote', p)
open(f, 'w', encoding='utf-8').write(s.replace(OLD, NEW))
print('patched', f, hashlib.md5(open(f, 'rb').read()).hexdigest())
